import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("INVENTORY_DB_URL");
    private static final String DB_USER = System.getenv("INVENTORY_DB_USER");
    private static final String DB_PASS = System.getenv("INVENTORY_DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String location = req.getParameter("location");
        String sortField = req.getParameter("sort");
        String tenantId = req.getHeader("X-Tenant-ID");

        // Validate tenant header presence
        if (tenantId == null || tenantId.isEmpty()) {
            resp.sendError(403, "Missing tenant context");
            return;
        }

        // Basic input sanitization for type and location
        if (assetType != null && !assetType.matches("[a-zA-Z0-9_-]+")) {
            resp.sendError(400, "Invalid asset type format");
            return;
        }
        if (location != null && !location.matches("[a-zA-Z0-9_/ -]+")) {
            resp.sendError(400, "Invalid location format");
            return;
        }

        // Build query - sort field is validated against allowlist... partially
        String baseQuery = "SELECT asset_id, asset_name, asset_type, location, status, last_scan_date " +
                          "FROM asset_inventory WHERE tenant_id = '" + tenantId + "'";

        if (assetType != null) {
            baseQuery += " AND asset_type = '" + assetType + "'";
        }
        if (location != null) {
            baseQuery += " AND location = '" + location + "'";
        }

        // Sort field handling - developer assumed header validation upstream
        if (sortField != null && !sortField.isEmpty()) {
            // Note: sort field comes from query param, not validated with regex above
            baseQuery += " ORDER BY " + sortField;
        } else {
            baseQuery += " ORDER BY last_scan_date DESC";
        }

        baseQuery += " LIMIT 100";

        logger.info("Asset query for tenant " + tenantId + ": type=" + assetType + ", loc=" + location);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(baseQuery)) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject asset = new JSONObject();
                asset.put("id", rs.getString("asset_id"));
                asset.put("name", rs.getString("asset_name"));
                asset.put("type", rs.getString("asset_type"));
                asset.put("location", rs.getString("location"));
                asset.put("status", rs.getString("status"));
                asset.put("lastScan", rs.getString("last_scan_date"));
                results.put(asset);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            logger.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Asset registration endpoint - uses PreparedStatement (safe)
        String tenantId = req.getHeader("X-Tenant-ID");
        if (tenantId == null) { resp.sendError(403); return; }

        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        try {
            JSONObject payload = new JSONObject(body.toString());
            String insertSQL = "INSERT INTO asset_inventory (tenant_id, asset_name, asset_type, location, status) VALUES (?, ?, ?, ?, ?)";

            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
                 PreparedStatement pstmt = conn.prepareStatement(insertSQL)) {
                pstmt.setString(1, tenantId);
                pstmt.setString(2, payload.getString("name"));
                pstmt.setString(3, payload.getString("type"));
                pstmt.setString(4, payload.getString("location"));
                pstmt.setString(5, "active");
                pstmt.executeUpdate();
            }
            resp.setStatus(201);
        } catch (Exception e) {
            resp.sendError(400, "Invalid payload");
        }
    }
}
